import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def calculate_ratio(n):
    # f(K_n) = number of triangles (K3) = C(n, 3)
    f_kn = combinations(n, 3)
    # g(K_n) = number of tetrahedra (K4) = C(n, 4)
    g_kn = combinations(n, 4)

    # Ratio = g(K_n)^3 / f(K_n)^4
    if f_kn == 0:
        return None # Should not happen for n >= 3

    numerator = g_kn**3
    denominator = f_kn**4

    # Return as fraction or float for comparison
    return numerator / denominator, (numerator, denominator)

N_values = [4, 5, 6, 7]
results = {}

for n in N_values:
    ratio_float, ratio_frac = calculate_ratio(n)
    results[n] = {
        "f(Kn)": combinations(n, 3),
        "g(Kn)": combinations(n, 4),
        "Ratio": ratio_float,
        "Fraction": ratio_frac
    }

print("Results:")
for n, data in results.items():
    print(f"--- n = {n} ---")
    print(f"f(K_{n}) = {data['f(Kn)']}")
    print(f"g(K_{n}) = {data['g(Kn)']}")
    print(f"Ratio g(K_n)^3 / f(K_n)^4 (Float): {data['Ratio']}")
    print(f"Ratio g(K_n)^3 / f(K_n)^4 (Fraction): {data['Fraction']}")

from math import comb

def ratio_Kn(n):
    if n < 4:
        return 0

    g_Kn = comb(n, 4)
    f_Kn = comb(n, 3)

    if f_Kn == 0:
        return float('inf')

    return (g_Kn**3) / (f_Kn**4)

# Test specific values and the asymptotic check
test_values = [4, 5, 6, 10]
print("R(K_n) for small n:")
for n in test_values:
    print(f"n={n}: {ratio_Kn(n)}")

